import{_ as t}from"./chunks/synth_basic.4aC2mAaW.js";import{_ as a}from"./chunks/synth_sid.DXoc36QV.js";import{_ as s}from"./chunks/synth_pocket.DKHPe-i5.js";import{_ as o}from"./chunks/synth_oh3.BkNeNxCu.js";import{_ as i}from"./chunks/synth_mechadrum.rVUZe1uD.js";import{_ as n,o as r,c as h,a2 as l}from"./chunks/framework.hw3Av5Vn.js";const S=JSON.parse('{"title":"Oscillators","description":"","frontmatter":{},"headers":[],"relativePath":"synths/OSCILLATORS.md","filePath":"synths/OSCILLATORS.md"}'),c={name:"synths/OSCILLATORS.md"};function d(p,e,m,f,u,g){return r(),h("div",null,[...e[0]||(e[0]=[l('<h1 id="oscillators" tabindex="-1">Oscillators <a class="header-anchor" href="#oscillators" aria-label="Permalink to &quot;Oscillators&quot;">​</a></h1><p>The Oscillators tab, the first of a built-in instrument&#39;s sound, holds the raw tone: what the filter, the envelopes and the effects then shape. It is where the engines differ most, and its Type chooses which oscillator it holds, so an engine&#39;s oscillator can be given to another engine&#39;s envelopes and filter. Each engine&#39;s page says how its oscillator is made.</p><p>The whole instrument&#39;s Voice settings, the same for every engine, are on the Engine tab, and are described at the end of this page.</p><h2 id="basic" tabindex="-1">Basic <a class="header-anchor" href="#basic" aria-label="Permalink to &quot;Basic&quot;">​</a></h2><p><img src="'+t+'" alt="The Oscillators tab of Basic"></p><p><a href="./engines/BASIC">Basic</a> describes it.</p><h2 id="sid" tabindex="-1">SID <a class="header-anchor" href="#sid" aria-label="Permalink to &quot;SID&quot;">​</a></h2><p><img src="'+a+'" alt="The Oscillators tab of SID"></p><p><a href="./engines/SID">SID</a> describes it.</p><h2 id="pocket" tabindex="-1">Pocket <a class="header-anchor" href="#pocket" aria-label="Permalink to &quot;Pocket&quot;">​</a></h2><p><img src="'+s+'" alt="The Oscillators tab of Pocket"></p><p><a href="./engines/POCKET">Pocket</a> describes it.</p><h2 id="oh3" tabindex="-1">Oh3 <a class="header-anchor" href="#oh3" aria-label="Permalink to &quot;Oh3&quot;">​</a></h2><p><img src="'+o+'" alt="The Oscillators tab of Oh3"></p><p><a href="./engines/OH3">Oh3</a> describes it.</p><h2 id="mechadrum" tabindex="-1">MechaDrum <a class="header-anchor" href="#mechadrum" aria-label="Permalink to &quot;MechaDrum&quot;">​</a></h2><p><img src="'+i+'" alt="The Oscillators tab of MechaDrum"></p><p><a href="./engines/MECHADRUM">MechaDrum</a> describes it.</p><h2 id="voice-settings" tabindex="-1">Voice Settings <a class="header-anchor" href="#voice-settings" aria-label="Permalink to &quot;Voice Settings&quot;">​</a></h2><p>The Engine tab of a LlamaSynth instrument holds what is the whole instrument&#39;s: Voices, how many notes sound at once; Glide, on unless switched off, whether the instrument slides into a glided step; Glide time, how long a note takes to slide; and, on an instrument of more than one voice, Filter, Per note, each note its own filter as on a polysynth, or Shared, one filter moved by the newest note, as on a paraphonic synth.</p><p>An instrument of one voice slides only where two notes overlap: a note that starts while the last is still held slides to its pitch over the Glide time, its envelopes going on, as a monosynth plays legato: a slid note restarts neither its amp envelope nor its filter&#39;s, on every engine. With Glide off, every note is struck afresh and the pattern&#39;s glided steps are ignored. Notes that only touch, one ending as the next starts, never slide; each is struck afresh. A step&#39;s Glide switch on the pattern is what makes a note run into the next, so the pattern says which notes slide and Glide time says how fast. An instrument of several voices plays an overlapping note on a voice of its own. An instrument of one voice given a chord plays its lowest note, as a monosynth&#39;s low-note priority does.</p>',21)])])}const T=n(c,[["render",d]]);export{S as __pageData,T as default};
